MagickBooleanType AutoGammaImage(Image *image, ExceptionInfo *exception) {
  double mean;
  double gamma;
  size_t channel;

  mean = GetImageMean(image, exception);
  if (fabs(mean) < MagickEpsilon)
    return (MagickBooleanType) MagickTrue;

  gamma = Log(mean) / Log(2.0);

  if (image->channel_mask == DefaultChannels) {
    if (AdjustImageGamma(image, gamma, exception) == MagickFalse)
      return (MagickBooleanType) MagickFalse;
  }
  else {
    for (channel = 0; channel < MaxChannel; channel++) {
      if ((image->channel_mask & (1UL << channel)) == 0)
        continue;

      mean = GetImageChannelMean(image, (ChannelType) (1UL << channel), exception);
      if (fabs(mean) < MagickEpsilon)
        continue;

      gamma = Log(mean) / Log(2.0);
      if (AdjustImageChannelGamma(image, (ChannelType) (1UL << channel), gamma, exception) == MagickFalse)
        return (MagickBooleanType) MagickFalse;
    }
  }

  return (MagickBooleanType) MagickTrue;
}

