{
  double mean;
  double gamma;
  MagickBooleanType status;
  ChannelType channel;

  if (image == (Image *) NULL)
    return(MagickFalse);

  status = MagickTrue;
  mean = GetImageMean(image, exception);
  if (mean == 0.0)
    return(MagickFalse);

  gamma = log(0.5 * mean + 0.5) / log(0.5);

  if (image->channel_mask == DefaultChannel)
  {
    if (AdjustImageGamma(image, gamma, exception) == MagickFalse)
      status = MagickFalse;
  }
