    for (channel = 0; channel < MaxChannel; channel++)
    {
      if ((1UL << channel) > image->channel_mask)
        continue;
      mean = GetImageMeanChannel(image, channel, exception);
      if (mean == 0.0)
        continue;
      gamma = log(0.5 * mean + 0.5) / log(0.5);
      if (AdjustImageGammaChannel(image, channel, gamma, exception) == MagickFalse)
        status = MagickFalse;
    }
  }

  return(status);
}
